[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>LearnForge — Build & Sell Online Courses, Coaching, Memberships & More</title>
<meta name="description" content="LearnForge is the all-in-one platform for creators to build, sell, and scale online education products including courses, coaching, digital downloads, and memberships.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet">
<style>
:root {
  --color-primary: oklch(10% 0.02 265);
  --color-accent: oklch(93% 0.21 115);
  --color-burgundy: oklch(30% 0.12 26);
  --color-white: oklch(100% 0 0);
  --color-bg: oklch(98.5% 0.01 265);
  --color-surface: oklch(100% 0 0);
  --color-text: oklch(18% 0.02 265);
  --color-text-muted: oklch(45% 0.02 265);
  --color-border: oklch(90% 0.01 265);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 16px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 32px oklch(0% 0 0 / 0.12);
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',sans-serif;color:var(--color-text);background:var(--color-bg);line-height:1.6;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4,h5,h6{font-family:'Plus Jakarta Sans',sans-serif;font-weight:700;line-height:1.15;letter-spacing:-0.02em}
h1{font-size:clamp(2.6rem,5vw,4rem)}
h2{font-size:clamp(2rem,3.5vw,2.8rem)}
h3{font-size:clamp(1.3rem,2vw,1.6rem)}
p{color:var(--color-text-muted)}
img{max-width:100%;display:block}
a{text-decoration:none;color:inherit}
ul{list-style:none}
.container{max-width:var(--max-width);margin:0 auto;padding:0 24px}
.section{padding:100px 0}
.section-label{display:inline-block;font-size:0.85rem;font-weight:700;text-transform:uppercase;letter-spacing:0.08em;color:var(--color-burgundy);margin-bottom:12px}
.section-title{margin-bottom:16px}
.section-subtitle{font-size:1.15rem;max-width:620px;margin-bottom:48px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 28px;border-radius:var(--radius-md);font-family:'Plus Jakarta Sans',sans-serif;font-weight:600;font-size:0.95rem;cursor:pointer;transition:var(--transition);border:none;white-space:nowrap}
.btn-primary{background:var(--color-accent);color:var(--color-primary)}
.btn-primary:hover{transform:translateY(-2px);box-shadow:var(--shadow-md)}
.btn-outline{background:transparent;color:var(--color-primary);border:2px solid var(--color-primary)}
.btn-outline:hover{background:var(--color-primary);color:var(--color-white)}
.btn-white{background:var(--color-white);color:var(--color-primary)}
.btn-white:hover{transform:translateY(-2px);box-shadow:var(--shadow-md)}

/* Navigation */
.nav{position:fixed;top:0;left:0;right:0;z-index:1000;background:oklch(100% 0 0 / 0.92);backdrop-filter:blur(12px);border-bottom:1px solid var(--color-border);transition:var(--transition)}
.nav .container{display:flex;align-items:center;justify-content:space-between;height:72px}
.nav-logo{font-family:'Plus Jakarta Sans',sans-serif;font-weight:800;font-size:1.5rem;letter-spacing:-0.03em;display:flex;align-items:center;gap:8px}
.nav-logo-icon{width:36px;height:36px;background:var(--color-accent);border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:center;font-size:1.2rem}
.nav-links{display:flex;align-items:center;gap:32px}
.nav-links a{font-weight:500;font-size:0.9rem;transition:var(--transition);position:relative}
.nav-links a::after{content:'';position:absolute;bottom:-4px;left:0;width:0;height:2px;background:var(--color-accent);transition:var(--transition)}
.nav-links a:hover::after{width:100%}
.nav-cta{padding:10px 22px;font-size:0.88rem}
.nav-toggle{display:none;background:none;border:none;cursor:pointer;padding:8px;flex-direction:column;gap:5px}
.nav-toggle span{display:block;width:24px;height:2px;background:var(--color-primary);transition:var(--transition)}

/* Hero */
.hero{padding:160px 0 80px;background:var(--color-white);overflow:hidden}
.hero .container{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.hero-content h1{margin-bottom:20px}
.hero-content .hero-subtitle{font-size:1.15rem;margin-bottom:32px}
.hero-ctas{display:flex;gap:14px;flex-wrap:wrap}
.hero-tabs{display:inline-flex;background:var(--color-bg);border-radius:var(--radius-xl);padding:4px;margin-bottom:28px}
.hero-tab{padding:10px 22px;border-radius:var(--radius-xl);font-size:0.88rem;font-weight:600;cursor:pointer;transition:var(--transition);border:none;background:transparent;font-family:'Plus Jakarta Sans',sans-serif}
.hero-tab.active{background:var(--color-primary);color:var(--color-white)}
.hero-visual{position:relative}
.hero-preview{background:var(--color-primary);border-radius:var(--radius-xl);padding:24px;min-height:380px;display:flex;align-items:center;justify-content:center;color:var(--color-white);position:relative;overflow:hidden}
.hero-preview-content{text-align:center;display:none}
.hero-preview-content.active{display:block}
.hero-preview-content h3{font-size:1.4rem;margin-bottom:8px}
.hero-preview-content p{color:oklch(100% 0 0 / 0.7);font-size:0.9rem}
.hero-preview-icon{font-size:3rem;margin-bottom:16px}
.hero-preview-dots{display:flex;gap:6px;margin-top:20px;justify-content:center}
.hero-preview-dot{width:8px;height:8px;border-radius:50%;background:oklch(100% 0 0 / 0.3)}
.hero-preview-dot.active{background:var(--color-accent)}

/* Stats Bar */
.stats-bar{background:var(--color-primary);padding:48px 0;position:relative}
.stats-bar .container{display:flex;justify-content:center;gap:80px;flex-wrap:wrap}
.stat-item{text-align:center}
.stat-number{font-family:'Plus Jakarta Sans',sans-serif;font-size:clamp(2rem,3.5vw,2.8rem);font-weight:800;color:var(--color-accent);display:block}
.stat-label{color:oklch(100% 0 0 / 0.7);font-size:0.95rem;margin-top:4px}

/* Products */
.products{background:var(--color-bg)}
.products .section-header{text-align:center;margin-bottom:56px}
.products .section-header .section-subtitle{margin:0 auto 48px}
.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.product-card{background:var(--color-surface);border-radius:var(--radius-lg);padding:36px 28px;box-shadow:var(--shadow-sm);transition:var(--transition);border:1px solid var(--color-border);text-align:center}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg)}
.product-card-icon{width:56px;height:56px;background:var(--color-accent);border-radius:var(--radius-md);display:flex;align-items:center;justify-content:center;font-size:1.5rem;margin:0 auto 20px}
.product-card h3{margin-bottom:10px}
.product-card p{font-size:0.92rem}
.product-card-link{display:inline-block;margin-top:16px;font-weight:600;font-size:0.9rem;color:var(--color-burgundy);transition:var(--transition)}
.product-card-link:hover{color:var(--color-primary)}

/* Why Choose Us */
.why-us{background:var(--color-white)}
.why-us .section-header{text-align:center;margin-bottom:48px}
.why-us .section-header .section-subtitle{margin:0 auto 48px}
.why-tabs{display:flex;justify-content:center;gap:8px;margin-bottom:40px;flex-wrap:wrap}
.why-tab{padding:12px 24px;border-radius:var(--radius-xl);font-size:0.9rem;font-weight:600;cursor:pointer;transition:var(--transition);border:2px solid var(--color-border);background:var(--color-white);font-family:'Plus Jakarta Sans',sans-serif;text-align:left}
.why-tab:hover{border-color:var(--color-primary)}
.why-tab.active{background:var(--color-primary);color:var(--color-white);border-color:var(--color-primary)}
.why-content{display:none;grid-template-columns:1fr 1fr;gap:48px;align-items:start}
.why-content.active{display:grid}
.why-visual{background:var(--color-bg);border-radius:var(--radius-xl);min-height:300px;display:flex;align-items:center;justify-content:center;font-size:4rem;color:var(--color-text-muted)}
.why-details h3{font-size:1.4rem;margin-bottom:20px}
.why-details ul{display:flex;flex-direction:column;gap:14px}
.why-details li{display:flex;align-items:flex-start;gap:12px;font-size:0.95rem;color:var(--color-text-muted)}
.why-details li::before{content:'✓';color:var(--color-accent);font-weight:700;font-size:1.1rem;flex-shrink:0;margin-top:1px;font-family:'Inter',sans-serif}

/* Global Scale */
.global-scale{background:var(--color-primary);color:var(--color-white)}
.global-scale .section-label{color:var(--color-accent)}
.global-scale .section-title{color:var(--color-white)}
.global-scale .section-subtitle{color:oklch(100% 0 0 / 0.65)}
.global-scale .container{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.global-visual{background:oklch(100% 0 0 / 0.05);border-radius:var(--radius-xl);min-height:320px;display:flex;align-items:center;justify-content:center;font-size:6rem}
.global-features{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:28px}
.global-feature{padding:20px;background:oklch(100% 0 0 / 0.06);border-radius:var(--radius-md)}
.global-feature h4{font-size:1rem;margin-bottom:6px;color:var(--color-white)}
.global-feature p{color:oklch(100% 0 0 / 0.6);font-size:0.88rem}

/* AI Automations */
.ai-automations{background:var(--color-bg)}
.ai-automations .section-header{text-align:center;margin-bottom:48px}
.ai-automations .section-header .section-subtitle{margin:0 auto 48px}
.ai-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.ai-card{background:var(--color-surface);border-radius:var(--radius-lg);padding:32px;box-shadow:var(--shadow-sm);border:1px solid var(--color-border);transition:var(--transition)}
.ai-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-md)}
.ai-card-icon{font-size:2rem;margin-bottom:16px}
.ai-card h3{font-size:1.15rem;margin-bottom:10px}
.ai-card p{font-size:0.92rem}

/* Testimonials */
.testimonials{background:var(--color-white)}
.testimonials .section-header{text-align:center;margin-bottom:48px}
.testimonials .section-header .section-subtitle{margin:0 auto 48px}
.testimonial-carousel{position:relative;max-width:800px;margin:0 auto;overflow:hidden}
.testimonial-track{display:flex;transition:transform 0.4s cubic-bezier(0.4, 0, 0.2, 1)}
.testimonial-card{min-width:100%;padding:0 16px}
.testimonial-card-inner{background:var(--color-bg);border-radius:var(--radius-xl);padding:40px;text-align:center}
.testimonial-label{display:inline-block;background:var(--color-accent);color:var(--color-primary);padding:4px 14px;border-radius:var(--radius-xl);font-size:0.8rem;font-weight:700;margin-bottom:16px}
.testimonial-quote{font-size:1.15rem;font-style:italic;margin-bottom:24px;color:var(--color-text)}
.testimonial-author{font-weight:700;font-size:1rem}
.testimonial-role{color:var(--color-text-muted);font-size:0.88rem}
.testimonial-controls{display:flex;justify-content:center;align-items:center;gap:16px;margin-top:28px}
.testimonial-btn{width:44px;height:44px;border-radius:50%;border:2px solid var(--color-border);background:var(--color-white);cursor:pointer;font-size:1.2rem;display:flex;align-items:center;justify-content:center;transition:var(--transition)}
.testimonial-btn:hover{border-color:var(--color-primary);background:var(--color-primary);color:var(--color-white)}
.testimonial-dots{display:flex;gap:8px}
.testimonial-dot{width:10px;height:10px;border-radius:50%;background:var(--color-border);border:none;cursor:pointer;transition:var(--transition)}
.testimonial-dot.active{background:var(--color-primary)}

/* Pricing */
.pricing{background:var(--color-bg)}
.pricing .section-header{text-align:center;margin-bottom:48px}
.pricing .section-header .section-subtitle{margin:0 auto 48px}
.pricing-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-bottom:36px}
.pricing-card{background:var(--color-surface);border-radius:var(--radius-lg);padding:32px 24px;box-shadow:var(--shadow-sm);border:1px solid var(--color-border);text-align:center;transition:var(--transition);position:relative}
.pricing-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-md)}
.pricing-card.featured{border-color:var(--color-accent);box-shadow:0 0 0 2px var(--color-accent)}
.pricing-card.featured::before{content:'Most Popular';position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:var(--color-accent);color:var(--color-primary);padding:4px 16px;border-radius:var(--radius-xl);font-size:0.75rem;font-weight:700}
.pricing-name{font-weight:700;font-size:1.1rem;margin-bottom:8px}
.pricing-price{font-family:'Plus Jakarta Sans',sans-serif;font-size:2.2rem;font-weight:800;margin-bottom:4px}
.pricing-period{font-size:0.85rem;color:var(--color-text-muted);margin-bottom:16px}
.pricing-fee{font-size:0.82rem;color:var(--color-text-muted);margin-bottom:16px;padding:8px;background:var(--color-bg);border-radius:var(--radius-sm)}
.pricing-cta{margin-top:8px;width:100%}
.pricing-trial{text-align:center;font-size:0.9rem;color:var(--color-text-muted)}
.pricing-trial a{color:var(--color-burgundy);font-weight:600}
.enterprise-card{background:var(--color-primary);color:var(--color-white);border-radius:var(--radius-lg);padding:36px 40px;display:flex;align-items:center;justify-content:space-between;gap:40px;margin-top:28px}
.enterprise-card h3{color:var(--color-white);margin-bottom:8px}
.enterprise-card p{color:oklch(100% 0 0 / 0.6);font-size:0.92rem}
.enterprise-card .btn{flex-shrink:0}

/* Integrations */
.integrations{background:var(--color-white)}
.integrations .section-header{text-align:center;margin-bottom:48px}
.integrations .section-header .section-subtitle{margin:0 auto 48px}
.integrations-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:16px}
.integration-item{display:flex;align-items:center;justify-content:center;padding:24px 16px;background:var(--color-bg);border-radius:var(--radius-md);font-weight:600;font-size:0.9rem;transition:var(--transition);border:1px solid transparent}
.integration-item:hover{border-color:var(--color-border);box-shadow:var(--shadow-sm);background:var(--color-surface)}

/* Social Proof */
.social-proof{background:var(--color-bg);text-align:center}
.social-proof .container{max-width:700px}
.social-proof h2{margin-bottom:16px}
.social-proof p{font-size:1.1rem;margin-bottom:28px}
.social-proof .btn{font-size:1rem;padding:16px 36px}

/* FAQ */
.faq{background:var(--color-white)}
.faq .section-header{text-align:center;margin-bottom:48px}
.faq .section-header .section-subtitle{margin:0 auto 48px}
.faq-list{max-width:720px;margin:0 auto}
.faq-item{border-bottom:1px solid var(--color-border)}
.faq-question{width:100%;padding:22px 0;display:flex;justify-content:space-between;align-items:center;font-size:1.05rem;font-weight:600;cursor:pointer;background:none;border:none;text-align:left;font-family:'Plus Jakarta Sans',sans-serif;transition:var(--transition)}
.faq-question:hover{color:var(--color-burgundy)}
.faq-icon{font-size:1.4rem;transition:var(--transition);flex-shrink:0;margin-left:16px}
.faq-item.active .faq-icon{transform:rotate(45deg)}
.faq-answer{max-height:0;overflow:hidden;transition:max-height 0.35s ease,padding 0.35s ease}
.faq-item.active .faq-answer{max-height:200px}
.faq-answer p{padding-bottom:20px;font-size:0.95rem}

/* CTA Banner */
.cta-banner{background:var(--color-primary);padding:80px 0;text-align:center}
.cta-banner h2{color:var(--color-white);margin-bottom:14px}
.cta-banner p{color:oklch(100% 0 0 / 0.65);margin-bottom:28px;font-size:1.1rem}
.cta-banner .btn{font-size:1rem;padding:16px 36px}

/* Footer */
.footer{background:var(--color-primary);color:oklch(100% 0 0 / 0.65);padding:72px 0 36px}
.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:48px;margin-bottom:48px}
.footer-brand .nav-logo{color:var(--color-white);margin-bottom:16px}
.footer-brand p{font-size:0.9rem;color:oklch(100% 0 0 / 0.5)}
.footer-col h4{color:var(--color-white);margin-bottom:20px;font-size:0.95rem}
.footer-col a{display:block;font-size:0.88rem;margin-bottom:10px;transition:var(--transition)}
.footer-col a:hover{color:var(--color-accent)}
.footer-bottom{border-top:1px solid oklch(100% 0 0 / 0.1);padding-top:28px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:16px;font-size:0.85rem}

/* Fade in animation */
.fade-in{opacity:0;transform:translateY(24px);transition:opacity 0.6s ease,transform 0.6s ease}
.fade-in.visible{opacity:1;transform:translateY(0)}

@media(max-width:1024px){
  .product-grid{grid-template-columns:repeat(2,1fr)}
  .why-content{grid-template-columns:1fr}
  .why-visual{min-height:200px}
  .global-scale .container{grid-template-columns:1fr}
  .pricing-cards{grid-template-columns:repeat(2,1fr)}
  .integrations-grid{grid-template-columns:repeat(3,1fr)}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
  .hero .container{grid-template-columns:1fr}
  .hero-visual{max-width:500px;margin:0 auto}
}
@media(max-width:768px){
  .nav-links{display:none;position:fixed;top:72px;left:0;right:0;background:var(--color-white);flex-direction:column;padding:24px;gap:16px;border-bottom:1px solid var(--color-border)}
  .nav-links.open{display:flex}
  .nav-toggle{display:flex}
  .product-grid{grid-template-columns:1fr}
  .why-tabs{flex-direction:column;align-items:stretch}
  .ai-grid{grid-template-columns:1fr}
  .pricing-cards{grid-template-columns:1fr}
  .integrations-grid{grid-template-columns:repeat(2,1fr)}
  .stats-bar .container{gap:40px}
  .enterprise-card{flex-direction:column;text-align:center}
  .hero{padding:120px 0 60px}
}
</style>
</head>
<body>

<nav class="nav" id="nav">
  <div class="container">
    <a href="index.html" class="nav-logo">
      <span class="nav-logo-icon">&#9670;</span> LearnForge
    </a>
    <button class="nav-toggle" id="navToggle" aria-label="Toggle navigation">
      <span></span><span></span><span></span>
    </button>
    <div class="nav-links" id="navLinks">
      <a href="online-courses.html">Online Courses</a>
      <a href="digital-downloads.html">Digital Downloads</a>
      <a href="memberships.html">Memberships</a>
      <a href="coaching.html">Coaching</a>
      <a href="#pricing" class="btn btn-primary nav-cta">Start Free Trial</a>
    </div>
  </div>
</nav>

<!-- Hero Section -->
<section class="hero" id="hero">
  <div class="container">
    <div class="hero-content fade-in">
      <h1>The future of your education business happens here</h1>
      <p class="hero-subtitle">Whatever your expertise—languages, fitness, or coding—LearnForge helps you deliver impactful learning, run a smarter business, and scale worldwide.</p>
      <div class="hero-tabs" id="heroTabs">
        <button class="hero-tab active" data-view="creator">Your view</button>
        <button class="hero-tab" data-view="student">Your student's view</button>
      </div>
      <div class="hero-ctas">
        <a href="#pricing" class="btn btn-primary">Start for free</a>
        <a href="#pricing" class="btn btn-outline">Explore our plans</a>
      </div>
    </div>
    <div class="hero-visual fade-in">
      <div class="hero-preview">
        <div class="hero-preview-content active" id="previewCreator">
          <div class="hero-preview-icon">&#9881;</div>
          <h3>Creator Dashboard</h3>
          <p>Manage courses, track revenue, and engage students — all from one place.</p>
          <div class="hero-preview-dots">
            <div class="hero-preview-dot active"></div>
            <div class="hero-preview-dot"></div>
            <div class="hero-preview-dot"></div>
          </div>
        </div>
        <div class="hero-preview-content" id="previewStudent">
          <div class="hero-preview-icon">&#128218;</div>
          <h3>Student Experience</h3>
          <p>Beautiful course player with progress tracking, quizzes, and mobile access.</p>
          <div class="hero-preview-dots">
            <div class="hero-preview-dot"></div>
            <div class="hero-preview-dot active"></div>
            <div class="hero-preview-dot"></div>
          </div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- Stats Bar -->
<section class="stats-bar">
  <div class="container">
    <div class="stat-item fade-in">
      <span class="stat-number">$12B+</span>
      <span class="stat-label">earned by LearnForge creators</span>
    </div>
    <div class="stat-item fade-in">
      <span class="stat-number">120M+</span>
      <span class="stat-label">students served on LearnForge</span>
    </div>
    <div class="stat-item fade-in">
      <span class="stat-number">180 countries</span>
      <span class="stat-label">using LearnForge</span>
    </div>
  </div>
</section>

<!-- Products -->
<section class="products section" id="products">
  <div class="container">
    <div class="section-header fade-in">
      <span class="section-label">Products</span>
      <h2 class="section-title">Everything you need to build your education empire</h2>
      <p class="section-subtitle">Four powerful product types to monetize your expertise, grow your audience, and scale your business.</p>
