<script>
(function(){
  // Mobile nav toggle
  const navToggle = document.getElementById('navToggle');
  const navLinks = document.getElementById('navLinks');
  navToggle.addEventListener('click',()=>{navLinks.classList.toggle('open')});

  // Hero tab switch
  const heroTabs = document.getElementById('heroTabs');
  const previewCreator = document.getElementById('previewCreator');
  const previewStudent = document.getElementById('previewStudent');
  heroTabs.addEventListener('click',(e)=>{
    if(!e.target.classList.contains('hero-tab'))return;
    heroTabs.querySelectorAll('.hero-tab').forEach(t=>t.classList.remove('active'));
    e.target.classList.add('active');
    const view = e.target.dataset.view;
    previewCreator.classList.toggle('active',view==='creator');
    previewStudent.classList.toggle('active',view==='student');
  });

  // Why Choose Us tabs
  const whyTabs = document.getElementById('whyTabs');
  whyTabs.addEventListener('click',(e)=>{
    if(!e.target.classList.contains('why-tab'))return;
    whyTabs.querySelectorAll('.why-tab').forEach(t=>t.classList.remove('active'));
    e.target.classList.add('active');
    document.querySelectorAll('.why-content').forEach(c=>c.classList.remove('active'));
    document.getElementById('whyContent'+e.target.dataset.tab).classList.add('active');
  });

  // Testimonial carousel
  let testimonialIndex = 0;
  const testimonialTrack = document.getElementById('testimonialTrack');
  const testimonialCards = testimonialTrack.querySelectorAll('.testimonial-card');
  const testimonialDots = document.getElementById('testimonialDots');
  const totalTestimonials = testimonialCards.length;

  for(let i=0;i<totalTestimonials;i++){
    const dot = document.createElement('button');
    dot.className = 'testimonial-dot'+(i===0?' active':'');
    dot.setAttribute('aria-label','Testimonial '+(i+1));
    dot.addEventListener('click',()=>goToTestimonial(i));
    testimonialDots.appendChild(dot);
  }

  function goToTestimonial(idx){
    testimonialIndex = idx;
    testimonialTrack.style.transform = 'translateX(-'+testimonialIndex+'00%)';
    testimonialDots.querySelectorAll('.testimonial-dot').forEach((d,i)=>d.classList.toggle('active',i===testimonialIndex));
  }

  document.getElementById('testimonialPrev').addEventListener('click',()=>{
    goToTestimonial((testimonialIndex-1+totalTestimonials)%totalTestimonials);
  });
  document.getElementById('testimonialNext').addEventListener('click',()=>{
    goToTestimonial((testimonialIndex+1)%totalTestimonials);
  });

  // FAQ accordions
  document.querySelectorAll('.faq-item').forEach(item=>{
    item.querySelector('.faq-question').addEventListener('click',()=>{
      const isActive = item.classList.contains('active');
      item.parentElement.querySelectorAll('.faq-item').forEach(sib=>sib.classList.remove('active'));
      if(!isActive) item.classList.add('active');
    });
  });

  // Scroll fade-in
  const observer = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')});
  },{threshold:0.1});
  document.querySelectorAll('.fade-in').forEach(el=>observer.observe(el));
})();
</script>
