(function(){
  document.getElementById('navToggle').addEventListener('click',()=>{
    document.getElementById('navLinks').classList.toggle('open');
  });

  // Product demo accordion
  const demoTrigger = document.getElementById('demoTrigger');
  const demoContent = document.getElementById('demoContent');
  demoTrigger.addEventListener('click',()=>{
    const isOpen = demoContent.classList.contains('open');
    demoContent.classList.toggle('open');
    demoTrigger.classList.toggle('active',!isOpen);
  });

  // Testimonial carousel
  let idx = 0;
  const track = document.getElementById('testimonialTrack');
  const cards = track.querySelectorAll('.testimonial-card');
  const dots = document.getElementById('testimonialDots');
  const total = cards.length;
  for(let i=0;i<total;i++){
    const d=document.createElement('button');
    d.className='testimonial-dot'+(i===0?' active':'');
    d.setAttribute('aria-label','Testimonial '+(i+1));
    d.addEventListener('click',()=>goTo(i));
    dots.appendChild(d);
  }
  function goTo(i){
    idx=i;
    track.style.transform='translateX(-'+idx+'00%)';
    dots.querySelectorAll('.testimonial-dot').forEach((d,j)=>d.classList.toggle('active',j===idx));
  }
  document.getElementById('testimonialPrev').addEventListener('click',()=>goTo((idx-1+total)%total));
  document.getElementById('testimonialNext').addEventListener('click',()=>goTo((idx+1)%total));

  // FAQ accordions
  document.querySelectorAll('.faq-item').forEach(item=>{
    item.querySelector('.faq-question').addEventListener('click',()=>{
      const was=item.classList.contains('active');
      item.parentElement.querySelectorAll('.faq-item').forEach(s=>s.classList.remove('active'));
      if(!was)item.classList.add('active');
    });
  });

  // Scroll fade-in
  const obs=new IntersectionObserver((entries)=>{
    entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')});
  },{threshold:0.1});
  document.querySelectorAll('.fade-in').forEach(el=>obs.observe(el));
})();
</script>
